css:
/* Flat One Dark surfaces. Typography overrides target actual UI text. */
:root {
  --font-sans: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}
body,
:is([data-slot="sidebar"], [data-chat-header], .messages-timeline-scroll, [data-user-message-bubble], .chat-markdown, [data-slot="composer-host"], .composer-tiptap, [data-thread-details-card], [data-settings-page-scroll], [data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="tooltip-popup"]),
[data-slot="button"],
[data-slot="input"],
[data-slot="select-trigger"] {
  font-family: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
  font-kerning: normal;
}
:is([data-slot="sidebar"], [data-chat-header], .messages-timeline-scroll, [data-user-message-bubble], .chat-markdown, [data-slot="composer-host"], .composer-tiptap, [data-thread-details-card], [data-settings-page-scroll], [data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="tooltip-popup"]) :where(p, span, a, button, input, textarea, div, label, h1, h2, h3, h4, h5, h6, li, td, th, summary, time):not(:where(code *, pre *, kbd *, samp *, .chat-markdown-codeblock, .chat-markdown-codeblock *, [data-thread-terminal-drawer], [data-thread-terminal-drawer] *)) {
  font-family: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}
.chat-markdown,
[data-user-message-bubble],
.composer-tiptap {
  font-size: 1rem;
  line-height: 1.65;
  letter-spacing: normal;
}
.chat-markdown :is(h1, h2, h3, h4, h5, h6) {
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.02em;
  text-wrap: balance;
}
.chat-markdown :is(strong, b) {
  font-weight: 600;
}
[data-chat-header], [data-thread-item] {
  letter-spacing: -0.01em;
}
:is(code, pre, kbd, samp, .chat-markdown-codeblock),
:is(code, pre, kbd, samp, .chat-markdown-codeblock) * {
  font-family: var(--font-mono, ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace) !important;
  letter-spacing: normal;
}

/* Continuous, non-repeating gradients; all colors switch with appearance. */
:root:not(.dark) {
  --od-shell-gradient: radial-gradient(ellipse at 0% 0%, #dceafa 0%, transparent 65%), linear-gradient(170deg, #eef2f8 0%, #eeeaf5 100%);
  --od-header-gradient: linear-gradient(100deg, #eaf2fc 0%, #f1f2f7 55%, #f1edf7 100%);
  --od-canvas-gradient: radial-gradient(ellipse at 100% 0%, #edf1fa 0%, transparent 55%), radial-gradient(ellipse at 0% 100%, #f3eef8 0%, transparent 50%);
  --od-composer-gradient: radial-gradient(ellipse at 0% 100%, #ecebf4 0%, #ecebf400 62%), radial-gradient(ellipse at 100% 0%, #f2e8df 0%, #f2e8df00 55%), linear-gradient(#faf9f6, #faf9f6);
  --od-composer-border: #ded8d5;
}
:root.dark {
  --od-shell-gradient: radial-gradient(ellipse at 0% 0%, #2a3a50 0%, transparent 65%), linear-gradient(170deg, #222833 0%, #2c2635 100%);
  --od-header-gradient: linear-gradient(100deg, #283447 0%, #252b36 55%, #2d2939 100%);
  --od-canvas-gradient: radial-gradient(ellipse at 100% 0%, #2c3241 0%, transparent 55%), radial-gradient(ellipse at 0% 100%, #302c3b 0%, transparent 50%);
  --od-composer-gradient: radial-gradient(ellipse at 100% 0%, #51443d 0%, #51443d00 55%), radial-gradient(ellipse at 0% 100%, #373341 0%, #37334100 65%), linear-gradient(#282c34, #282c34);
  --od-composer-border: #524a4b;
}
[data-slot="sidebar"] {
  background: var(--od-shell-gradient) !important;
  background-repeat: no-repeat !important;
  background-size: 100% 100% !important;
}
[data-slot="sidebar-inner"] {
  background: transparent !important;
}
[data-chat-header] {
  background: var(--od-header-gradient) !important;
  background-repeat: no-repeat !important;
}
[data-workspace-area="conversation"] {
  background-image: var(--od-canvas-gradient) !important;
  background-repeat: no-repeat !important;
  background-size: 100% 100% !important;
}
[data-slot="composer-host"] {
  background: var(--od-composer-gradient) !important;
  background-repeat: no-repeat !important;
  border-color: var(--od-composer-border) !important;
}

:root.dark {
  --od-title-gradient: linear-gradient(105deg, #1f2c3c 0%, #222e41 12.5%, #243145 25%, #283349 37.5%, #2b354d 50%, #2f3750 62.5%, #333953 75%, #373b57 87.5%, #3b3d5a 100%);
  --od-title-text: #edf0fa;
  --od-title-hover: #ffffff12;
}
:root:not(.dark) {
  --od-title-gradient: linear-gradient(105deg, #e0edfc 0%, #dfebfc 12.5%, #dee9fc 25%, #dee8fb 37.5%, #dde6fb 50%, #dde4fb 62.5%, #dde3fa 75%, #dde1fa 87.5%, #dddff9 100%);
  --od-title-text: #303a51;
  --od-title-hover: #303a5110;
}

[data-chat-header] {
  background: var(--od-title-gradient) left top / 100vw 52px no-repeat fixed !important;
}
@property --od-working-phase {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}
@keyframes od-working-clock {
  from { --od-working-phase: 0; }
  to { --od-working-phase: 1; }
}
:root.dark {
  --od-sidebar-solid: #303641;
  --od-working-gradient: linear-gradient(110deg, #354e70 0%, #494a70 35%, #34576a 68%, #354e70 100%);
  --od-working-text: #edf2fc;
}
:root:not(.dark) {
  --od-sidebar-solid: #f3f5f9;
  --od-working-gradient: linear-gradient(110deg, #d6e7ff 0%, #e6dcfa 35%, #d3edf4 68%, #d6e7ff 100%);
  --od-working-text: #293b58;
}
[data-slot="sidebar"] {
  background: var(--od-sidebar-solid) !important;
  animation: od-working-clock 7s ease-in-out infinite alternate;
}
[data-slot="sidebar-inner"] {
  background: transparent !important;
}
[data-thread-item] [data-sidebar-row][aria-label*="Working"] {
  background-image: var(--od-working-gradient) !important;
  background-size: 240% 100% !important;
  background-position: calc(var(--od-working-phase) * 100%) 50% !important;
  color: var(--od-working-text) !important;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="sidebar"] {
    animation: none;
    --od-working-phase: 0.5;
  }
}

/* Readable hint text against the composer reflections. */
:root.dark { --od-composer-placeholder: #b8becb; }
:root:not(.dark) { --od-composer-placeholder: #626977; }
.composer-tiptap [data-placeholder]::before,
.composer-tiptap::before {
  color: var(--od-composer-placeholder) !important;
}
